-- Same migration as supabase/migrations/20261127210000_transport_facts.sql.
-- Prefer the supabase/migrations copy: GitHub Actions applies that folder.

-- Transport, taxi, airport, and route_model facts (step 2 of 3).
-- Additive only: new tables. No changes to users, miniapp_*, reviews, events,
-- user_states, or to 20261127064000_guide_facts.sql.
--
-- User zone is the 24.11.2026 rule, not the point formula in config/trust_config.json.
-- Airport facts: official + confirmed = green; unconfirmed or non-official = yellow.
-- Ride services: green only when status is «подтверждено» and the URL is official;
-- «требует проверки владельцем» or a secondary source = yellow.
-- Taxi tariff from a user_screenshot = yellow.
-- route_model tables keep the JSON shape. Their zone is still computed by the
-- live trust engine, so these tables do not store a zone column.
--
-- owner_check and legacy are internal (owner notes, raw source objects, screenshot
-- notes). anon and authenticated have no SELECT on those columns. A role with
-- column privileges cannot use SELECT * on the table, so the notes are not
-- returned. The *_public views are the select=* shape: security_invoker, no
-- internal columns, RLS still applies.
-- Telegram and forum URLs are not written to public source columns.
--
-- The seed below is generated by scripts/seed_transport_facts.py.
-- Merging this file to main runs .github/workflows/supabase_deploy.yml against production.
-- Do not apply it before the owner says so.

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE IF NOT EXISTS public.airport_facts (
    id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    source_key text NOT NULL,
    country_slug text NOT NULL REFERENCES public.countries (slug),
    airport_code text NOT NULL,
    topic text NOT NULL,
    fact text NOT NULL,
    zone text NOT NULL CHECK (zone IN ('green', 'yellow', 'red')),
    status text NOT NULL CHECK (status IN ('active', 'outdated', 'refuted', 'gap')),
    source_url text,
    source_type text,
    source_is_official boolean NOT NULL,
    checked_at date NOT NULL,
    needs_owner_check boolean NOT NULL DEFAULT false,
    decision_needed text,
    unknown_zone text,
    legacy jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT airport_facts_source_key_key UNIQUE (source_key)
);

CREATE TABLE IF NOT EXISTS public.ride_services (
    id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    source_key text NOT NULL,
    service text NOT NULL,
    category text NOT NULL,
    country_iso2 text NOT NULL,
    country_slug text NOT NULL,
    city text,
    status text NOT NULL CHECK (status IN ('подтверждено', 'требует проверки владельцем')),
    zone text NOT NULL CHECK (zone IN ('green', 'yellow', 'red')),
    source_url text,
    availability text,
    payment text,
    account text,
    interface_lang text,
    ru_store_vpn text,
    airport text,
    pricing text,
    check_date date NOT NULL,
    store_source text,
    owner_check text,
    legacy jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ride_services_source_key_key UNIQUE (source_key)
);

CREATE TABLE IF NOT EXISTS public.taxi_tariff_rules (
    id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    source_key text NOT NULL,
    country_iso2 text NOT NULL,
    service text NOT NULL,
    zone_label text NOT NULL,
    captured_at timestamptz NOT NULL,
    source_kind text NOT NULL,
    currency text NOT NULL,
    note text,
    tariffs jsonb NOT NULL,
    zone text NOT NULL CHECK (zone IN ('green', 'yellow', 'red')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT taxi_tariff_rules_source_key_key UNIQUE (source_key)
);

CREATE TABLE IF NOT EXISTS public.transport_routes (
    id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    source_key text NOT NULL,
    title text NOT NULL,
    departure_city_id text NOT NULL,
    destination_slug text NOT NULL REFERENCES public.countries (slug),
    origin_iata text NOT NULL,
    iata text NOT NULL,
    tickets jsonb NOT NULL,
    payment_targets jsonb NOT NULL,
    airline_fact text,
    lead_facts jsonb NOT NULL,
    sections jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT transport_routes_source_key_key UNIQUE (source_key)
);

CREATE TABLE IF NOT EXISTS public.transport_measurements (
    id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    source_key text NOT NULL,
    kind text,
    gap boolean NOT NULL DEFAULT false,
    value_num numeric,
    value_text text,
    value_min numeric,
    value_max numeric,
    unit text,
    template text,
    statement text,
    source_url text,
    source_kind text,
    source_date date,
    agreement text,
    volatility text NOT NULL,
    transfer_topic text,
    transfer_measure text,
    verified_by_us boolean NOT NULL DEFAULT false,
    details jsonb NOT NULL DEFAULT '{}'::jsonb,
    legacy jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT transport_measurements_source_key_key UNIQUE (source_key)
);

CREATE TABLE IF NOT EXISTS public.transport_rules (
    id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    source_key text NOT NULL,
    evaluated_on date NOT NULL,
    ticket_url text NOT NULL,
    payment_phrase text NOT NULL,
    payment_button text NOT NULL,
    units jsonb NOT NULL,
    integer_group integer NOT NULL,
    integer_group_from integer NOT NULL,
    volatility_classes jsonb NOT NULL,
    engine_volatility jsonb NOT NULL,
    formulas jsonb NOT NULL,
    slot_joiner text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT transport_rules_source_key_key UNIQUE (source_key)
);

-- country_slug and destination_slug are foreign keys. Postgres does not index them.
CREATE INDEX IF NOT EXISTS idx_airport_facts_country_airport
    ON public.airport_facts (country_slug, airport_code);
CREATE INDEX IF NOT EXISTS idx_airport_facts_zone ON public.airport_facts (zone);
CREATE INDEX IF NOT EXISTS idx_airport_facts_checked_at ON public.airport_facts (checked_at);
CREATE INDEX IF NOT EXISTS idx_ride_services_country_service
    ON public.ride_services (country_iso2, service);
CREATE INDEX IF NOT EXISTS idx_ride_services_country_slug ON public.ride_services (country_slug);
CREATE INDEX IF NOT EXISTS idx_ride_services_zone ON public.ride_services (zone);
CREATE INDEX IF NOT EXISTS idx_taxi_tariff_rules_country_service
    ON public.taxi_tariff_rules (country_iso2, service);
CREATE INDEX IF NOT EXISTS idx_transport_routes_destination
    ON public.transport_routes (destination_slug);
CREATE INDEX IF NOT EXISTS idx_transport_measurements_volatility
    ON public.transport_measurements (volatility);
CREATE INDEX IF NOT EXISTS idx_transport_measurements_topic
    ON public.transport_measurements (transfer_topic, transfer_measure);

ALTER TABLE public.airport_facts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ride_services ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.taxi_tariff_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transport_routes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transport_measurements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transport_rules ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS airport_facts_public_read ON public.airport_facts;
CREATE POLICY airport_facts_public_read ON public.airport_facts
    FOR SELECT
    TO anon, authenticated
    USING (true);

DROP POLICY IF EXISTS ride_services_public_read ON public.ride_services;
CREATE POLICY ride_services_public_read ON public.ride_services
    FOR SELECT
    TO anon, authenticated
    USING (true);

DROP POLICY IF EXISTS taxi_tariff_rules_public_read ON public.taxi_tariff_rules;
CREATE POLICY taxi_tariff_rules_public_read ON public.taxi_tariff_rules
    FOR SELECT
    TO anon, authenticated
    USING (true);

DROP POLICY IF EXISTS transport_routes_public_read ON public.transport_routes;
CREATE POLICY transport_routes_public_read ON public.transport_routes
    FOR SELECT
    TO anon, authenticated
    USING (true);

DROP POLICY IF EXISTS transport_measurements_public_read ON public.transport_measurements;
CREATE POLICY transport_measurements_public_read ON public.transport_measurements
    FOR SELECT
    TO anon, authenticated
    USING (true);

DROP POLICY IF EXISTS transport_rules_public_read ON public.transport_rules;
CREATE POLICY transport_rules_public_read ON public.transport_rules
    FOR SELECT
    TO anon, authenticated
    USING (true);

-- Data API: since 2026-10-30 new public tables get no default grants.
-- Writes stay on service_role. Public reads are column-scoped where a table
-- holds owner_check or legacy.
REVOKE ALL ON TABLE
    public.airport_facts,
    public.ride_services,
    public.taxi_tariff_rules,
    public.transport_routes,
    public.transport_measurements,
    public.transport_rules
FROM PUBLIC, anon, authenticated;

GRANT SELECT (
    id,
    source_key,
    country_slug,
    airport_code,
    topic,
    fact,
    zone,
    status,
    source_url,
    source_type,
    source_is_official,
    checked_at,
    needs_owner_check,
    decision_needed,
    unknown_zone,
    created_at,
    updated_at
) ON TABLE public.airport_facts TO anon, authenticated;

GRANT SELECT (
    id,
    source_key,
    service,
    category,
    country_iso2,
    country_slug,
    city,
    status,
    zone,
    source_url,
    availability,
    payment,
    account,
    interface_lang,
    ru_store_vpn,
    airport,
    pricing,
    check_date,
    store_source,
    created_at,
    updated_at
) ON TABLE public.ride_services TO anon, authenticated;

GRANT SELECT ON TABLE public.taxi_tariff_rules TO anon, authenticated;
GRANT SELECT ON TABLE public.transport_routes TO anon, authenticated;

GRANT SELECT (
    id,
    source_key,
    kind,
    gap,
    value_num,
    value_text,
    value_min,
    value_max,
    unit,
    template,
    statement,
    source_url,
    source_kind,
    source_date,
    agreement,
    volatility,
    transfer_topic,
    transfer_measure,
    verified_by_us,
    details,
    created_at,
    updated_at
) ON TABLE public.transport_measurements TO anon, authenticated;

GRANT SELECT ON TABLE public.transport_rules TO anon, authenticated;

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE
    public.airport_facts,
    public.ride_services,
    public.taxi_tariff_rules,
    public.transport_routes,
    public.transport_measurements,
    public.transport_rules
TO service_role;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;

DROP VIEW IF EXISTS public.airport_facts_public;
CREATE VIEW public.airport_facts_public
WITH (security_invoker = true) AS
SELECT
    id,
    source_key,
    country_slug,
    airport_code,
    topic,
    fact,
    zone,
    status,
    source_url,
    source_type,
    source_is_official,
    checked_at,
    needs_owner_check,
    decision_needed,
    unknown_zone,
    created_at,
    updated_at
FROM public.airport_facts;

DROP VIEW IF EXISTS public.ride_services_public;
CREATE VIEW public.ride_services_public
WITH (security_invoker = true) AS
SELECT
    id,
    source_key,
    service,
    category,
    country_iso2,
    country_slug,
    city,
    status,
    zone,
    source_url,
    availability,
    payment,
    account,
    interface_lang,
    ru_store_vpn,
    airport,
    pricing,
    check_date,
    store_source,
    created_at,
    updated_at
FROM public.ride_services;

DROP VIEW IF EXISTS public.transport_measurements_public;
CREATE VIEW public.transport_measurements_public
WITH (security_invoker = true) AS
SELECT
    id,
    source_key,
    kind,
    gap,
    value_num,
    value_text,
    value_min,
    value_max,
    unit,
    template,
    statement,
    source_url,
    source_kind,
    source_date,
    agreement,
    volatility,
    transfer_topic,
    transfer_measure,
    verified_by_us,
    details,
    created_at,
    updated_at
FROM public.transport_measurements;

REVOKE ALL ON TABLE
    public.airport_facts_public,
    public.ride_services_public,
    public.transport_measurements_public
FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE
    public.airport_facts_public,
    public.ride_services_public,
    public.transport_measurements_public
TO anon, authenticated;

