('route_model:rules', '2026-10-18'::date, 'https://www.aviasales.ru/search/{origin}{date}{destination}1?marker={marker}', 'Компас оплаты → {title}', 'Компас оплаты · {title}', '{"cny": ["юань", "юаня", "юаней"], "days": ["день", "дня", "дней"], "days_cap": ["дня", "дней", "дней"], "hkd": ["гонконгский доллар", "гонконгских доллара", "гонконгских долларов"], "hours": ["час", "часа", "часов"], "inches": ["дюйм", "дюйма", "дюймов"], "minutes": ["минута", "минуты", "минут"], "seats": ["место", "места", "мест"], "thb": ["бат", "бата", "батов"], "usd": ["доллар США", "доллара США", "долларов США"], "years_cap": ["года", "лет", "лет"]}'::jsonb, 3, 1000, '{"conflict": "расхождение источников", "map": "оценка карты", "open": "источник не дал одного числа", "operator": "оператор", "owner": "проверено нами", "schedule": "расписание", "statute": "правило"}'::jsonb, '{"operator": "medium", "schedule": "fast", "statute": "slow"}'::jsonb, '{"airport_change_allowance": "Сумма минут: value_max (если есть, иначе value) переезда плюс value минимальной стыковки. Надбавки сверх суммы нет. Если вход — пробел или его нет, совет не считается и становится пробелом. Зона совета — худшая зона опор по шкале trust_config. Пока route_rules.allow_map_estimate_in_allowance выключен, оценки карты в сумму не входят. Если включен, вместо входов из driving_replaces берётся максимум value_max оценок из driving_inputs. Минимальная стыковка всё равно нужна.", "allowance_gap": "Сколько времени закладывать на смену аэропорта {pair} — не исследовано.", "allowance_text": "На стыковку со сменой аэропорта {pair} закладывайте {value} {unit_label}: это сумма максимального переезда и минимальной стыковки.", "driving_no_range_note": " Карта даёт одну цифру на вариант, без диапазона по пробкам.", "driving_slot_interval": "каждые {value} {unit_label}", "driving_slot_label": "{label}: {duration}", "driving_slot_range": "от {value_min} до {value_max} {unit_label}", "driving_slot_single": "{value} {unit_label}", "driving_summary": "На машине, {direction}: {slots}.", "format_date": "Поле value в формате YYYY-MM-DD показывается как ДД.ММ.ГГГГ.", "format_range": "Подставляет value_min и value_max. unit_label склоняется по value_max.", "format_value": "Подставляет value измерения и unit_label. Число в шаблоне не пишется. Целое не меньше integer_group_from показывается группами шириной integer_group.", "grab_cross_check": "Сверка времени Grab и карты, {direction}, {when_label}: {slots}.", "grab_inside_map": "внутри диапазона карты ({slot})", "grab_outside_map": "не целиком внутри диапазона карты ({slot})", "transit_summary": "Общественный транспорт, {direction}: {slots}.", "volatility_class": "Метка на измерении: правило, оператор, расписание, расхождение источников, открытый пробел или оценка карты. Для балла метка правила, оператора и расписания сопоставляется с классом свежести в engine_volatility. Если заданы transfer_topic и transfer_measure, класс берётся из transfer_measures в trust_config: время в пути отдельно от цены, такси, интервала и расписания. Зону считает живой движок trust_config. Пробел и совет свою зону из балла не получают."}'::jsonb, ', ')
